    #[test]
    fn optional_parameter_properties_include_undefined_without_strict_null_checks() {
        let parsed = parse_source_file("class C { constructor(public value?: string) {} }");
        let bindings = bind_source_file(&parsed.arena, parsed.source_file);
        let result = check_source_file_with_options(
            &parsed.arena,
            parsed.source_file,
            &bindings,
            CheckerOptions {
                strict_null_checks: false,
                ..CheckerOptions::default()
            },
        );
        let class = bindings.root_scope().unwrap().symbols.get("C").unwrap();
        let class_type = result.type_of_symbol(class).unwrap();
        let TypeKind::Object(object) = &result.types.get(class_type).unwrap().kind else {
            panic!("expected class instance type");
        };
        let value = object.properties["value"];
        assert!(object.optional_properties.contains("value"));
        assert!(matches!(
            &result.types.get(value).unwrap().kind,
            TypeKind::Union(members) if members.contains(&result.types.undefined())
        ));
    }

    #[test]
    fn inferred_binding_default_properties_include_undefined() {
        let parsed = parse_source_file("const fn = ({ headers = {} }) => {};");
        let bindings = bind_source_file(&parsed.arena, parsed.source_file);
        let result = check_source_file(&parsed.arena, parsed.source_file, &bindings);
        let function = bindings.root_scope().unwrap().symbols.get("fn").unwrap();
        let function_type = result.type_of_symbol(function).unwrap();
        let TypeKind::Function(function) = &result.types.get(function_type).unwrap().kind else {
            panic!("expected function type");
        };
        let TypeKind::Object(options) = &result.types.get(function.parameters[0]).unwrap().kind
        else {
            panic!("expected object parameter");
        };
        assert!(options.optional_properties.contains("headers"));
        let TypeKind::Union(members) =
            &result.types.get(options.properties["headers"]).unwrap().kind
        else {
            panic!("expected optional property union");
        };
        assert!(members.contains(&result.types.undefined()));
    }

    #[test]
    fn infers_class_expression_constructor_and_instance_types() {
        let parsed = parse_source_file(
            r#"
                const Box = class NamedBox {
                    constructor(public readonly value: string) {}
                    method(): string { return this.value; }
                };
                const Empty = class {};
                const box = new Box("ok");
                const text: string = box.value;
                box.value = "changed";
                new Box(1);
                Box();
            "#,
        );
        assert!(parsed.diagnostics.is_empty(), "{:?}", parsed.diagnostics);
        let bindings = bind_source_file(&parsed.arena, parsed.source_file);
        assert!(
            bindings.diagnostics.is_empty(),
            "{:?}",
            bindings.diagnostics
        );
        let result = check_source_file(&parsed.arena, parsed.source_file, &bindings);
        assert_eq!(
            result
                .diagnostics
                .iter()
                .map(|diagnostic| diagnostic.diagnostic.code())
                .collect::<Vec<_>>(),
            [2540, 2345, 2349]
        );

        let box_symbol = bindings.root_scope().unwrap().symbols.get("Box").unwrap();
        let constructor_type = result.type_of_symbol(box_symbol).unwrap();
        let TypeKind::Constructor(constructor) = &result.types.get(constructor_type).unwrap().kind
        else {
            panic!("expected constructor type");
        };
        assert_eq!(constructor.parameters, [result.types.string()]);
        let TypeKind::Object(instance) = &result.types.get(constructor.return_type).unwrap().kind
        else {
            panic!("expected instance type");
        };
        assert!(instance.properties.contains_key("value"));
        assert!(instance.properties.contains_key("method"));
        assert!(instance.readonly_properties.contains("value"));
        let empty_symbol = bindings.root_scope().unwrap().symbols.get("Empty").unwrap();
        let empty_type = result.type_of_symbol(empty_symbol).unwrap();
        let TypeKind::Constructor(empty_constructor) = &result.types.get(empty_type).unwrap().kind
        else {
            panic!("expected anonymous class constructor type");
        };
        assert!(empty_constructor.parameters.is_empty());
        assert!(matches!(
            result
                .types
                .get(empty_constructor.return_type)
                .unwrap()
                .kind,
            TypeKind::Object(_)
        ));

        let declaration = bindings.symbols.get(box_symbol).unwrap().declarations[0];
        assert_eq!(result.type_of_node(declaration), Some(constructor_type));
        let NodeData::VariableDeclaration(variable) = &parsed.arena.get(declaration).unwrap().data
        else {
            panic!("expected variable declaration");
        };
        assert_eq!(
            result.type_of_node(variable.initializer.unwrap()),
            Some(constructor_type)
        );
    }

    #[test]
