    #[test]
    fn infers_anonymous_class_function_returns_and_inherited_parameter_properties() {
        let parsed = parse_source_file(
            r"
                export class X {
                    constructor(readonly a: number) {}
                }
                export function y() {
                    return class extends X {};
                }
            ",
        );
        assert!(parsed.diagnostics.is_empty(), "{:?}", parsed.diagnostics);
        let bindings = bind_source_file(&parsed.arena, parsed.source_file);
        let result = check_source_file(&parsed.arena, parsed.source_file, &bindings);
        assert!(result.diagnostics.is_empty(), "{:?}", result.diagnostics);

        let y = bindings.root_scope().unwrap().symbols.get("y").unwrap();
        let y_declaration = bindings.symbols.get(y).unwrap().declarations[0];
        let y_type = result.type_of_symbol(y).unwrap();
        assert_eq!(result.type_of_node(y_declaration), Some(y_type));
        let TypeKind::Function(y_signature) = &result.types.get(y_type).unwrap().kind else {
            panic!("expected function type");
        };
        let TypeKind::Constructor(constructor) =
            &result.types.get(y_signature.return_type).unwrap().kind
        else {
            panic!("expected anonymous class constructor return");
        };
        assert_eq!(constructor.parameters, [result.types.number()]);
        let TypeKind::Object(instance) = &result.types.get(constructor.return_type).unwrap().kind
        else {
            panic!("expected anonymous class instance");
        };
        assert_eq!(instance.properties.get("a"), Some(&result.types.number()));
        assert!(instance.readonly_properties.contains("a"));

        let NodeData::FunctionDeclaration(y_function) =
            &parsed.arena.get(y_declaration).unwrap().data
        else {
            panic!("expected function declaration");
        };
        let body = y_function.body.unwrap();
        let NodeData::Block(body) = &parsed.arena.get(body).unwrap().data else {
            panic!("expected function body");
        };
        let NodeData::ReturnStatement(return_statement) =
            &parsed.arena.get(body.statements.nodes[0]).unwrap().data
        else {
            panic!("expected return statement");
        };
        assert_eq!(
            result.type_of_node(return_statement.expression.unwrap()),
            Some(y_signature.return_type)
        );
    }

    #[test]
    #[allow(clippy::too_many_lines)] // One fixture walk.
    fn infers_auto_accessor_types_from_owning_class_writes() {
        let parsed = parse_source_file(
            r"
                class Example {
                    accessor test;
                    constructor(test: number) { this.test = test; }
                }
                class Example2 {
                    accessor test;
                    constructor(test: number | undefined) { this.test = test; }
                }
                class Example3 {
                    accessor value;
                    constructor(n: number) {
                        this.value = n;
                        if (n < 0) this.value = null;
                    }
                }
                declare var n: number;
                class Example4 {
                    static accessor value;
                    static {
                        this.value = n;
                        if (n < 0) this.value = null;
                    }
                }
                class Example5 { static accessor value; }
                Example5.value = 123;
                Example5.value++;
                class Example6 {
                    static accessor x;
                    static { this.x = 1; }
                    static accessor y = this.x;
                    static accessor z;
                    static { this.z = this.y; }
                }
            ",
        );
        assert!(parsed.diagnostics.is_empty(), "{:?}", parsed.diagnostics);
        let bindings = bind_source_file(&parsed.arena, parsed.source_file);
        let result = check_source_file_with_options(
            &parsed.arena,
            parsed.source_file,
            &bindings,
            CheckerOptions {
                no_implicit_any: true,
                ..CheckerOptions::default()
            },
        );

        let accessor_type = |class_name: &str, property_name: &str| {
            parsed
                .arena
                .iter()
                .find_map(|(node_id, node)| {
                    let NodeData::PropertyDeclaration(property) = &node.data else {
                        return None;
                    };
                    if identifier_text(&parsed.arena, property.name) != Some(property_name) {
                        return None;
                    }
                    let parent = node.parent?;
                    let NodeData::ClassDeclaration(class) = &parsed.arena.get(parent)?.data else {
                        return None;
                    };
                    (class
                        .name
                        .and_then(|name| identifier_text(&parsed.arena, name))
                        == Some(class_name))
                    .then(|| result.type_of_node(node_id).unwrap())
                })
                .unwrap()
        };
        let assert_union = |type_id, expected: &[super::TypeId]| {
            let TypeKind::Union(members) = &result.types.get(type_id).unwrap().kind else {
                panic!("expected union type");
            };
            assert_eq!(members.len(), expected.len());
            assert!(expected.iter().all(|expected| members.contains(expected)));
        };

        assert_eq!(accessor_type("Example", "test"), result.types.number());
        assert_union(
            accessor_type("Example2", "test"),
            &[result.types.number(), result.types.undefined()],
        );
        assert_union(
            accessor_type("Example3", "value"),
            &[result.types.number(), result.types.null()],
        );
        assert_union(
            accessor_type("Example4", "value"),
            &[result.types.number(), result.types.null()],
        );
        assert_eq!(accessor_type("Example5", "value"), result.types.any());
        assert_eq!(accessor_type("Example6", "z"), result.types.number());
        assert_eq!(
            result
                .diagnostics
                .iter()
                .map(|diagnostic| diagnostic.diagnostic.code())
                .collect::<Vec<_>>(),
            [18046, 7008]
        );
    }

    #[test]
