    #[test]
    #[allow(clippy::too_many_lines)]
    fn infers_default_library_and_class_static_method_return_types() {
        let default_library = parse_source_file(
            r"
                interface DateConstructor { now(): number; }
                declare var Date: DateConstructor;
                interface Collection<T> { item: T; }
                interface CollectionConstructor { create(): Collection<number>; }
                declare var Collection: CollectionConstructor;
            ",
        );
        let consumer = parse_source_file(
            r"
                class Clock { static now(): number { return 1; } }
                const clockNow = Clock.now();
                declare const collection: Collection<number>;
                const collectionItem = collection.item;
                Collection.create();
                export function makeTimestamped() {
                    return class {
                        timestamp = Date.now();
                        localTimestamp = Clock.now();
                    };
                }
            ",
        );
        assert!(
            default_library.diagnostics.is_empty(),
            "{:?}",
            default_library.diagnostics
        );
        assert!(
            consumer.diagnostics.is_empty(),
            "{:?}",
            consumer.diagnostics
        );
        let default_bindings =
            bind_source_file(&default_library.arena, default_library.source_file);
        let consumer_bindings = bind_source_file(&consumer.arena, consumer.source_file);
        let no_modules = BTreeMap::new();
        let checked = check_program(&[
            ProgramSource {
                arena: &default_library.arena,
                source_file: default_library.source_file,
                bindings: &default_bindings,
                resolved_modules: &no_modules,
                is_default_library: true,
                skip_diagnostics: true,
                checker_options: CheckerOptions {
                    is_declaration_file: true,
                    ..CheckerOptions::default()
                },
            },
            ProgramSource {
                arena: &consumer.arena,
                source_file: consumer.source_file,
                bindings: &consumer_bindings,
                resolved_modules: &no_modules,
                is_default_library: false,
                skip_diagnostics: false,
                checker_options: CheckerOptions::default(),
            },
        ]);
        assert!(
            checked.files[1].diagnostics.is_empty(),
            "{:?}",
            checked.files[1].diagnostics
        );

        let clock_now = consumer_bindings
            .root_scope()
            .unwrap()
            .symbols
            .get("clockNow")
            .unwrap();
        assert_eq!(
            checked.files[1].type_of_symbol(clock_now),
            Some(checked.files[1].types.number())
        );
        let collection_item = consumer_bindings
            .root_scope()
            .unwrap()
            .symbols
            .get("collectionItem")
            .unwrap();
        assert_eq!(
            checked.files[1].type_of_symbol(collection_item),
            Some(checked.files[1].types.number())
        );
        let make = consumer_bindings
            .root_scope()
            .unwrap()
            .symbols
            .get("makeTimestamped")
            .unwrap();
        let make_type = checked.files[1].type_of_symbol(make).unwrap();
        let TypeKind::Function(make) = &checked.files[1].types.get(make_type).unwrap().kind else {
            panic!("expected function type");
        };
        let TypeKind::Constructor(returned_class) =
            &checked.files[1].types.get(make.return_type).unwrap().kind
        else {
            panic!("expected returned class constructor");
        };
        let TypeKind::Object(instance) = &checked.files[1]
            .types
            .get(returned_class.return_type)
            .unwrap()
            .kind
        else {
            panic!("expected returned class instance");
        };
        assert_eq!(
            instance.properties.get("timestamp"),
            Some(&checked.files[1].types.number())
        );
        assert_eq!(
            instance.properties.get("localTimestamp"),
            Some(&checked.files[1].types.number())
        );
        let timestamp_property = consumer
            .arena
            .iter()
            .find_map(|(node_id, node)| {
                let NodeData::PropertyDeclaration(property) = &node.data else {
                    return None;
                };
                (identifier_text(&consumer.arena, property.name) == Some("timestamp"))
                    .then_some(node_id)
            })
            .unwrap();
        assert_eq!(
            checked.files[1].type_of_node(timestamp_property),
            Some(checked.files[1].types.number())
        );
    }

    #[test]
    fn infers_ambient_const_literal_declaration_types() {
        let parsed = parse_source_file(
            r#"
                function f<T>(x: T): T { return x; }
                enum E { A, B, C }
                const c1 = "abc";
                const c2 = 123;
                const c3 = c1;
                const c4 = c2;
                const c5 = f(123);
                const c6 = f(-123);
                const c7 = true;
                const c8 = E.A;
                const c8b = E["A"];
                const c9 = { x: "abc" };
                const c10 = [123];
                const c11 = "abc" + "def";
                const c12 = 123 + 456;
                const c13 = true ? "abc" : "def";
                const c14 = true ? 123 : 456;
            "#,
        );
        assert!(parsed.diagnostics.is_empty(), "{:?}", parsed.diagnostics);
        let bindings = bind_source_file(&parsed.arena, parsed.source_file);
        let result = check_source_file(&parsed.arena, parsed.source_file, &bindings);
        assert!(result.diagnostics.is_empty(), "{:?}", result.diagnostics);
        let root = bindings.root_scope().unwrap();
        let type_of = |name: &str| {
            result
                .type_of_symbol(root.symbols.get(name).unwrap())
                .unwrap()
        };

        for (name, expected) in [
            ("c1", TypeKind::StringLiteral("abc".into())),
            ("c2", TypeKind::NumberLiteral("123".into())),
            ("c3", TypeKind::StringLiteral("abc".into())),
            ("c4", TypeKind::NumberLiteral("123".into())),
            ("c5", TypeKind::NumberLiteral("123".into())),
            ("c6", TypeKind::NumberLiteral("-123".into())),
            ("c7", TypeKind::BooleanLiteral(true)),
            ("c8", TypeKind::NumberLiteral("0".into())),
            ("c8b", TypeKind::NumberLiteral("0".into())),
            ("c11", TypeKind::String),
            ("c12", TypeKind::Number),
            ("c13", TypeKind::String),
            ("c14", TypeKind::Number),
        ] {
            assert_eq!(
                result.types.get(type_of(name)).unwrap().kind,
                expected,
                "{name}"
            );
            let symbol = root.symbols.get(name).unwrap();
            let declaration = bindings.symbols.get(symbol).unwrap().declarations[0];
            assert_eq!(
                result.type_of_node(declaration),
                Some(type_of(name)),
                "{name}"
            );
        }
        let TypeKind::Object(object) = &result.types.get(type_of("c9")).unwrap().kind else {
            panic!("expected widened object type");
        };
        assert_eq!(object.properties["x"], result.types.string());
        let TypeKind::Array(element) = result.types.get(type_of("c10")).unwrap().kind else {
            panic!("expected widened array type");
        };
        assert_eq!(element, result.types.number());
    }

    #[test]
    fn array_inference_reduces_redundant_optional_function_subtypes() {
        let parsed = parse_source_file(concat!(
            "declare const anyValue: any;",
            "const mixed = [1, anyValue];",
            "const cases = [",
            "(value: string) => {}, (value?: string) => {},",
            "(value: number) => {}, (value?: number) => {},",
            "(value: string[]) => {}, (value?: string[]) => {},",
            "];",
        ));
        assert!(parsed.diagnostics.is_empty(), "{:?}", parsed.diagnostics);
        let bindings = bind_source_file(&parsed.arena, parsed.source_file);
        let result = check_source_file(&parsed.arena, parsed.source_file, &bindings);
        assert!(result.diagnostics.is_empty(), "{:?}", result.diagnostics);
        let cases = bindings.root_scope().unwrap().symbols.get("cases").unwrap();
        let cases_type = result.type_of_symbol(cases).unwrap();
        let TypeKind::Array(element) = result.types.get(cases_type).unwrap().kind else {
            panic!("expected array");
        };
        let TypeKind::Union(members) = &result.types.get(element).unwrap().kind else {
            panic!("expected function union");
        };
        assert_eq!(members.len(), 3);
        assert!(members.iter().all(|member| matches!(
            result.types.get(*member).map(|type_| &type_.kind),
            Some(TypeKind::Function(signature)) if !signature.parameters_optional
        )));

        let mixed = bindings.root_scope().unwrap().symbols.get("mixed").unwrap();
        let mixed_type = result.type_of_symbol(mixed).unwrap();
        assert!(matches!(
            result.types.get(mixed_type).map(|type_| &type_.kind),
            Some(TypeKind::Array(element))
                if matches!(
                    result.types.get(*element).map(|type_| &type_.kind),
                    Some(TypeKind::Any)
                )
        ));
    }

