    #[test]
    fn retains_named_generic_alias_provenance_through_call_inference() {
        let parsed = parse_source_file(
            "type Box<T> = { get: () => T; set: (value: T) => void }; declare function box<T>(value: T): Box<T>; const value = box(0);",
        );
        let bindings = bind_source_file(&parsed.arena, parsed.source_file);
        let result = check_source_file(&parsed.arena, parsed.source_file, &bindings);
        let value = bindings.root_scope().unwrap().symbols.get("value").unwrap();
        let type_id = result.type_of_symbol(value).unwrap();
        let reference = result
            .named_type_references
            .get(&type_id)
            .unwrap_or_else(|| {
                panic!(
                    "missing Box provenance for {}",
                    result.types.display(type_id)
                )
            });
        assert_eq!(reference.name, "Box");
        assert_eq!(reference.type_arguments, [result.types.number()]);
    }

    #[test]
    fn retains_named_aliases_across_nested_generic_intersection_inference() {
        let parsed = parse_source_file(concat!(
            "type ModuleWithState<T> = { state: T };",
            "type MoreState = { z: string };",
            "declare function create<T, A>(state: T, actions: A): ModuleWithState<T> & A;",
            "declare function convert<T, A>(value: ModuleWithState<T> & A): ModuleWithState<T & MoreState> & A;",
            "const value = convert(create({ a: 12 }, { foo() { return true } }));",
        ));
        let bindings = bind_source_file(&parsed.arena, parsed.source_file);
        let result = check_source_file(&parsed.arena, parsed.source_file, &bindings);
        let value = bindings.root_scope().unwrap().symbols.get("value").unwrap();
        let declaration = bindings.symbols.get(value).unwrap().declarations[0];
        let type_id = result.node_types[&declaration];
        let TypeKind::Intersection(members) = &result.types.get(type_id).unwrap().kind else {
            panic!("expected intersection: {}", result.types.display(type_id));
        };
        let references = members
            .iter()
            .filter_map(|member| result.named_type_references.get(member))
            .filter(|reference| reference.name == "ModuleWithState")
            .collect::<Vec<_>>();
        assert_eq!(
            references.len(),
            2,
            "type: {}; members: {members:?}; named: {:?}",
            result.types.display(type_id),
            result.named_type_references
        );
    }

    #[test]
    fn defaults_uninferred_overload_type_parameters_to_unknown() {
        let parsed = parse_source_file(
            r"
                declare function noArgs(): string;
                declare function proxy<T, U>(fn: (options: T) => U): (options: T) => U;
                declare function proxy<T, U>(fn: (options?: T) => U, noArgs: true): (options?: T) => U;
                const value = proxy(noArgs, true);
            ",
        );
        let bindings = bind_source_file(&parsed.arena, parsed.source_file);
        let result = check_source_file(&parsed.arena, parsed.source_file, &bindings);
        let value = bindings.root_scope().unwrap().symbols.get("value").unwrap();
        let type_id = result.type_of_symbol(value).unwrap();

        let Some(TypeKind::Function(signature)) =
            result.types.get(type_id).map(|type_| &type_.kind)
        else {
            panic!("expected function, got {:?}", result.types.get(type_id));
        };
        assert!(signature.parameters_optional);
        let Some(TypeKind::Union(parameters)) = result
            .types
            .get(signature.parameters[0])
            .map(|type_| &type_.kind)
        else {
            panic!("expected optional union");
        };
        assert!(parameters.iter().any(|parameter| {
            matches!(
                result.types.get(*parameter).map(|type_| &type_.kind),
                Some(TypeKind::Unknown)
            )
        }));
    }

    #[test]
    fn preserves_explicit_nested_arrow_type_parameter_returns() {
        let parsed = parse_source_file("const o = <T>(value: T) => (): T => null!;");
        let bindings = bind_source_file(&parsed.arena, parsed.source_file);
        let result = check_source_file(&parsed.arena, parsed.source_file, &bindings);
        let o = bindings.root_scope().unwrap().symbols.get("o").unwrap();
        let outer_type = result.type_of_symbol(o).unwrap();
        let TypeKind::Function(outer) = &result.types.get(outer_type).unwrap().kind else {
            panic!("expected outer function");
        };
        let TypeKind::Function(inner) = &result.types.get(outer.return_type).unwrap().kind else {
            panic!("expected inner function");
        };

        assert_eq!(inner.return_type, outer.parameters[0]);
    }

    #[test]
    fn preserves_shadowed_nested_arrow_type_parameters() {
        let parsed = parse_source_file(
            "const foo = <T>(x: T) => { const inner = <T>(y: T) => [x, y] as const; return inner; };",
        );
        let bindings = bind_source_file(&parsed.arena, parsed.source_file);
        let result = check_source_file(&parsed.arena, parsed.source_file, &bindings);
        let foo = bindings.root_scope().unwrap().symbols.get("foo").unwrap();
        let outer_type = result.type_of_symbol(foo).unwrap();
        let TypeKind::Function(outer) = &result.types.get(outer_type).unwrap().kind else {
            panic!("expected outer function");
        };
        let TypeKind::Function(inner) = &result.types.get(outer.return_type).unwrap().kind else {
            panic!("expected inner function");
        };
        let TypeKind::ReadonlyTuple(elements) = &result.types.get(inner.return_type).unwrap().kind
        else {
            panic!("expected readonly tuple");
        };

        assert_eq!(result.types.display(elements[0]), "T");
        assert_eq!(result.types.display(elements[1]), "T_1");
        assert!(
            result
                .named_type_references
                .get(&outer.return_type)
                .is_some_and(|reference| reference.name == "__generic_function:T_1=0")
        );
    }

