    #[test]
    fn infers_calls_through_source_ordered_namespace_members() {
        let parsed = parse_source_file(concat!(
            "namespace source { export function value() { return 'ok'; } }\n",
            "export namespace consumer { ",
            "export function value() { return source.value(); } }",
        ));
        let bindings = bind_source_file(&parsed.arena, parsed.source_file);
        let result = check_source_file(&parsed.arena, parsed.source_file, &bindings);
        assert!(result.diagnostics.is_empty(), "{:?}", result.diagnostics);
        let consumer = bindings
            .root_scope()
            .and_then(|scope| scope.symbols.get("consumer"))
            .and_then(|symbol| bindings.symbols.get(symbol))
            .expect("consumer namespace is bound");
        let value = consumer
            .members
            .get("value")
            .and_then(|symbol| result.type_of_symbol(symbol))
            .expect("consumer.value has a semantic type");
        let TypeKind::Function(signature) = &result.types.get(value).unwrap().kind else {
            panic!("consumer.value should be a function");
        };
        assert_eq!(result.types.display(signature.return_type), "string");
    }

    #[test]
    fn preserves_exported_type_queries_and_private_const_literals_in_descriptors() {
        let parsed = parse_source_file(concat!(
            "export const publicValue = 'public';\n",
            "const privateValue = 'private';\n",
            "export const read = (a: typeof publicValue, b: typeof privateValue) => ",
            "null! as { public: typeof publicValue; private: typeof privateValue };\n",
        ));
        let bindings = bind_source_file(&parsed.arena, parsed.source_file);
        let result = check_source_file(&parsed.arena, parsed.source_file, &bindings);
        let modules = BTreeMap::new();
        let source = ProgramSource {
            arena: &parsed.arena,
            source_file: parsed.source_file,
            bindings: &bindings,
            resolved_modules: &modules,
            is_default_library: false,
            skip_diagnostics: false,
            checker_options: CheckerOptions::default(),
        };
        let symbol = bindings.root_scope().unwrap().symbols.get("read").unwrap();
        let TypeDescriptor::Function {
            parameters,
            return_type,
            ..
        } = ProgramChecker::describe_symbol(&source, &result, symbol).unwrap()
        else {
            panic!("expected function descriptor");
        };
        assert!(matches!(
            &parameters[0],
            TypeDescriptor::Named { name, .. } if name == "typeof publicValue"
        ));
        assert_eq!(
            parameters[1],
            TypeDescriptor::StringLiteral("private".into())
        );
        let TypeDescriptor::Object { properties, .. } = *return_type else {
            panic!("expected object return descriptor");
        };
        assert!(matches!(
            &properties["public"],
            TypeDescriptor::Named { name, .. } if name == "typeof publicValue"
        ));
        assert_eq!(
            properties["private"],
            TypeDescriptor::StringLiteral("private".into())
        );
    }

