    #[test]
    fn requires_delete_operands_to_be_optional() {
        let parsed = parse_source_file(
            r"
                interface Foo {
                    a: number;
                    b: number | undefined;
                    c: number | null;
                    d?: number;
                    e: number | undefined | null;
                    f?: number | undefined | null;
                    g: unknown;
                    h: any;
                    i: never;
                }
                declare const value: Foo;
                delete value.a;
                delete value.b;
                delete value.c;
                delete value.d;
                delete value.e;
                delete value.f;
                delete value.g;
                delete value.h;
                delete value.i;
            ",
        );
        assert!(parsed.diagnostics.is_empty(), "{:?}", parsed.diagnostics);
        let bindings = bind_source_file(&parsed.arena, parsed.source_file);

        let exact = check_source_file_with_options(
            &parsed.arena,
            parsed.source_file,
            &bindings,
            CheckerOptions {
                exact_optional_property_types: true,
                strict_null_checks: true,
                ..CheckerOptions::default()
            },
        );
        assert_eq!(
            exact
                .diagnostics
                .iter()
                .map(|diagnostic| diagnostic.diagnostic.code())
                .collect::<Vec<_>>(),
            [2790, 2790, 2790, 2790]
        );

        let legacy = check_source_file_with_options(
            &parsed.arena,
            parsed.source_file,
            &bindings,
            CheckerOptions {
                strict_null_checks: true,
                ..CheckerOptions::default()
            },
        );
        assert_eq!(
            legacy
                .diagnostics
                .iter()
                .map(|diagnostic| diagnostic.diagnostic.code())
                .collect::<Vec<_>>(),
            [2790, 2790]
        );

        let loose = check_source_file_with_options(
            &parsed.arena,
            parsed.source_file,
            &bindings,
            CheckerOptions {
                strict_null_checks: false,
                ..CheckerOptions::default()
            },
        );
        assert!(loose.diagnostics.is_empty(), "{:?}", loose.diagnostics);
    }

    #[test]
    fn empty_array_literals_widen_to_any_without_strict_null_checks() {
        let parsed = parse_source_file("export function make() { return []; }");
        assert!(parsed.diagnostics.is_empty(), "{:?}", parsed.diagnostics);
        let bindings = bind_source_file(&parsed.arena, parsed.source_file);
        let array = parsed
            .arena
            .iter()
            .find_map(|(id, node)| {
                matches!(node.data, NodeData::ArrayLiteralExpression(_)).then_some(id)
            })
            .unwrap();

        let loose = check_source_file_with_options(
            &parsed.arena,
            parsed.source_file,
            &bindings,
            CheckerOptions {
                strict_null_checks: false,
                ..CheckerOptions::default()
            },
        );
        let TypeKind::Array(loose_element) = &loose
            .types
            .get(*loose.node_types.get(&array).unwrap())
            .unwrap()
            .kind
        else {
            panic!("expected array type");
        };
        assert_eq!(*loose_element, loose.types.any());

        let strict = check_source_file(&parsed.arena, parsed.source_file, &bindings);
        let TypeKind::Array(strict_element) = &strict
            .types
            .get(*strict.node_types.get(&array).unwrap())
            .unwrap()
            .kind
        else {
            panic!("expected array type");
        };
        assert_eq!(*strict_element, strict.types.never());
    }

    #[test]
    fn loose_array_literals_ignore_nullish_elements_when_finding_a_common_type() {
        let parsed = parse_source_file(
            "let x; const first = [3, (3, null)]; const second = [3, (x = null)]; const nil = [null];",
        );
        assert!(parsed.diagnostics.is_empty(), "{:?}", parsed.diagnostics);
        let bindings = bind_source_file(&parsed.arena, parsed.source_file);
        let checked = check_source_file_with_options(
            &parsed.arena,
            parsed.source_file,
            &bindings,
            CheckerOptions {
                strict_null_checks: false,
                ..CheckerOptions::default()
            },
        );
        let mut arrays = parsed
            .arena
            .iter()
            .filter_map(|(id, node)| {
                matches!(node.data, NodeData::ArrayLiteralExpression(_))
                    .then_some((node.range.start, id))
            })
            .collect::<Vec<_>>();
        arrays.sort_by_key(|(start, _)| *start);
        let element = |array: NodeId| {
            let TypeKind::Array(element) = &checked
                .types
                .get(*checked.node_types.get(&array).unwrap())
                .unwrap()
                .kind
            else {
                panic!("expected array type");
            };
            *element
        };
        assert_eq!(element(arrays[0].1), checked.types.number());
        assert_eq!(element(arrays[1].1), checked.types.number());
        assert_eq!(element(arrays[2].1), checked.types.any());
    }

    #[test]
    fn resolves_self_referential_static_class_initializers() {
        let parsed = parse_source_file(
            r"
                class Point {
                    constructor(public x: number, public y: number) {}
                    getDist() { return this.x + this.y; }
                    static origin = new Point(0, 0);
                }
                const point: Point = Point.origin;
            ",
        );
        assert!(parsed.diagnostics.is_empty(), "{:?}", parsed.diagnostics);
        let bindings = bind_source_file(&parsed.arena, parsed.source_file);
        let result = check_source_file(&parsed.arena, parsed.source_file, &bindings);
        assert!(result.diagnostics.is_empty(), "{:?}", result.diagnostics);

        let point = bindings.root_scope().unwrap().symbols.get("Point").unwrap();
        let point_type = result.type_of_symbol(point).unwrap();
        let TypeKind::Object(point) = &result.types.get(point_type).unwrap().kind else {
            panic!("expected Point instance type");
        };
        assert!(point.properties.contains_key("x"));
        assert!(point.properties.contains_key("y"));
        assert!(point.properties.contains_key("getDist"));
        assert!(point.properties.contains_key("origin"));
    }

    #[test]
    fn evaluates_recursive_conditional_alias_after_generic_call_inference() {
        let parsed = parse_source_file(
            r#"
                type Record<K extends string, T> = { [P in K]: T };
                type Wrapper<T> = { _type: T };
                declare function stringWrapper(): Wrapper<string>;
                declare function objWrapper<T extends Record<string, Wrapper<any>>>(obj: T): Wrapper<T>;
                const value = objWrapper({ prop1: stringWrapper() as Wrapper<"hello"> });
                type Unwrap<T> = T extends Wrapper<any>
                    ? T["_type"] extends Record<string, Wrapper<any>>
                        ? { [Key in keyof T["_type"]]: Unwrap<T["_type"][Key]> }
                        : T["_type"]
                    : never;
                declare function unwrap<T>(wrapper: T): Unwrap<T>;
                const unwrapped = unwrap(value);
                const hello: "hello" = unwrapped.prop1;
            "#,
        );
        assert!(parsed.diagnostics.is_empty(), "{:?}", parsed.diagnostics);
        let bindings = bind_source_file(&parsed.arena, parsed.source_file);
        let result = check_source_file(&parsed.arena, parsed.source_file, &bindings);
        let value = bindings.root_scope().unwrap().symbols.get("value").unwrap();
        let unwrapped = bindings
            .root_scope()
            .unwrap()
            .symbols
            .get("unwrapped")
            .unwrap();
        assert_eq!(
            result.types.display(result.type_of_symbol(value).unwrap()),
            "{ _type: { prop1: { _type: \"hello\"; }; }; }"
        );
        assert_eq!(
            result
                .types
                .display(result.type_of_symbol(unwrapped).unwrap()),
            "{ prop1: \"hello\"; }"
        );
        assert!(
            result.diagnostics.is_empty(),
            "{:?}",
            result
                .diagnostics
                .iter()
                .map(|diagnostic| diagnostic.diagnostic.render().unwrap())
                .collect::<Vec<_>>()
        );
    }

